# -*- coding: utf-8 -*-
"""
Dance Registry for NAO
========================
Named dance routines that can be looked up by string key.
GPT picks an ordering from the registry; song_listener executes them.

Usage:
    from tone_dance import get_available_dances, execute_dance, stand_pose
    names = get_available_dances()           # ["raise_the_roof", "disco", ...]
    execute_dance(motion_proxy, "disco")     # run one dance
    stand_pose(motion_proxy)                 # safe standing posture
"""

import time


