# -- Registry --------------------------------------------------------------
# Maps a string key -> (display_name, function, approx_duration_seconds).
# To add a new dance: define the function above, then add one entry here.

DANCE_REGISTRY = {
    "raise_the_roof": ("Raise the Roof", raise_the_roof, 3.6),
    "disco":          ("Disco",          disco,          3.24),
    "sprinkler":      ("Sprinkler",      sprinkler,      7.16),
    "vacuum":         ("Vacuum",         vacuum,         24.52),
    "tai_chi":        ("Tai Chi",        tai_chi,        49.8),
    "elephant":       ("Elephant",       elephant,       6.84),
    "gorilla":        ("Gorilla",        gorilla,        10.68),
    "saxophone":      ("Saxophone",      saxophone,      9.84),
}


def get_available_dances():
    """Return the list of dance key strings (sent to GPT for choreography)."""
    return list(DANCE_REGISTRY.keys())


def execute_dance(motion, dance_name):
    """Look up *dance_name* in the registry and execute it.
    Returns True on success, False if the name is unknown or an error occurs."""
    entry = DANCE_REGISTRY.get(dance_name)
    if entry is None:
        print("[DanceRegistry] Unknown dance: '{}'".format(dance_name))
        return False

    display, func, _dur = entry
    print("[DanceRegistry] Playing: {}".format(display))
    try:
        func(motion)
        return True
    except Exception as e:
        print("[DanceRegistry] Error in '{}': {}".format(display, e))
        return False


def stand_pose(motion):
    """Move NAO to a safe neutral standing posture (~1.5s transition)."""
    names = [
        "HeadPitch", "HeadYaw",
        "LShoulderPitch", "LShoulderRoll", "LElbowYaw", "LElbowRoll",
        "LWristYaw", "LHand",
        "RShoulderPitch", "RShoulderRoll", "RElbowYaw", "RElbowRoll",
        "RWristYaw", "RHand",
    ]
    angles = [
        -0.17,  0.0,
         1.45,  0.15, -1.20, -0.52,
         0.0,   0.30,
         1.45, -0.15,  1.20,  0.52,
         0.0,   0.30,
    ]
    speed = 0.25
    try:
        motion.setAngles(names, angles, speed)
        time.sleep(1.5)
    except Exception as e:
        print("[DanceRegistry] stand_pose error: {}".format(e))
